      "inputSha256": "4437d6c3ada238fc65ae265a8d32c454441693031bfc9336efbe6dff82b91466",
      "caution": "원문에서 변제기와 ‘두 달이 지난’ 변제일이 모두 2021.12.16.로 되어 있어 날짜가 모순된다. 답안 각주2의 연도 ‘198.8.11.’도 불완전하다. 추측하여 교정하지 않았다.",
