      "sections": [
        {
          "heading": "암기용 답안",
          "points": [
            {
              "text": "기판력은 소송물에 관한 주문 판단에 생기며 이유 중 항변에는 원칙적으로 없다(216조 1항). 예외로 상계 자동채권은 이유 중 판단도 대항액 한도에서 기판력이 생긴다(216조 2항). 이는 상계에 사용해 소멸한 채권의 재청구로 상대방에게 이중 불이익을 주는 것을 막기 위함이다.\n\n요건은 ① 자동채권 존부의 실질적 판단—실기각하·상계금지·상계부적상 배척에는 없음 ② 실제 대항액 한도 ③ 수동채권이 소송물로 심판대상일 것이다. 동시이행항변의 반대채권을 수동채권으로 한 상계재항변에는 ③이 없다(2004다17207; 민법536조).\n\n따라서 갑의 대여금채권 부존재 판단에는 기판력이 없고, 을의 기판력 항변은 부당하다. 다만 전소의 부존재 사실인정은 특별한 사정 없으면 유력한 증거자료이므로 후소에서는 그 증명효를 고려하여 청구기각할 수 있다.",
              "sourceIds": [
                "class-4주-문1:s0:p3",
                "class-4주-문1:s0:p4",
                "class-4주-문1:s0:p5",
                "class-4주-문1:s0:p7",
                "class-4주-문1:s0:p8",
                "class-4주-문1:s0:p9",
                "class-4주-문1:s0:p11",
                "class-4주-문1:s0:p12"
              ],
              "authored": true
            }
          ]
        }
      ],
      "sourceUnits": [
        {
          "id": "class-4주-문1:s0:p0",
          "text": "문1.",
          "kind": "heading",
          "sha256": "74f4cf4c3d556a2707d6c410b32709cbc401976f72a7be3c2525f26235acf2c8",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p1",
          "text": "1. 문제의 소재(쟁점) : 기판력의 객관적 범위, 상계항변에 제공된 채권에 대하여 기판력이 인정되는 범위 - 2점",
          "kind": "heading",
          "sha256": "140571a072004960f80ae6c2485bf953571ec8871868f49d2c6da4c36892e712",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p2",
          "text": "2. 기판력의 객관적 범위 - 7점",
          "kind": "heading",
          "sha256": "b54a3a410136ac7c09ba2530996ecd2ff309fe1a75b5a5b23d8d8af73b881e8d",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p3",
          "text": "- 판결주문에서 한 판단에 한하여 기판력이 인정되며(제216조 제1항), 판결이유 중의 항변사항에 대해서는 그것이 판결주문의 결론을 내리는 기초가 되었다 하더라도 기판력이 생기지 않음",
          "kind": "argument",
          "sha256": "fbf1bfba5ac0babe4838f2ffaffde695bd7f6c238dabf4b2a1b146d51ab4fabc",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p4",
          "text": "- 다만 상계항변은 예외. 피고가 상계항변을 제출하고 법원이 자동채권의 존부에 관하여 판결이유에서 판단하였을 경우에는 상계로써 대항한 액수의 한도 내에서 기판력이 발생함(제216조 제2항).",
          "kind": "argument",
          "sha256": "c0713471963ba641b2a1b247c82bea8b7631d523a815594e9de9b5f249aeba33",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p5",
          "text": "- 판결이유 중의 판단임에도 상계 주장에 관한 법원의 판단에 기판력을 인정한 취지",
          "kind": "argument",
          "sha256": "6e24bb0e42be80b608051337158ae28351a9079b7ab9e17e5fedb666dc6b8d3f",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p6",
          "text": "3. 상계항변의 경우 기판력의 인정 범위 - 8점",
          "kind": "heading",
          "sha256": "0ded0faad724d7b16c904b52948e1b1c9db3ad55b50865d4ea9854b1f1a4b1f5",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p7",
          "text": "- 자동채권의 존부에 관하여 실질적인 판단이 있었을 것 . 상계항변의 실기각하, 상계금지, 상계부적상 등의 이유로 상계항변이 배척된 경우에는 기판력이 발생하지 않음. 상계로써 대항한 액수에 한하여 기판력 발생",
          "kind": "argument",
          "sha256": "8addab99929c728d90a95c0e18018fe202a4ff2aa9bbbd3239f9e62129f7884f",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p8",
          "text": "- 수동채권이 소송물로서 심판의 대상일 것",
          "kind": "argument",
          "sha256": "483494e06404613013881a67bb1842fd949f4a5f90898208cddef0aa4b8b5ced",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p9",
          "text": "• 대법원 2005. 7. 22. 선고 2004다17207 판결의 결론 및 취지",
          "kind": "argument",
          "sha256": "210363705b0534b94a6c0a0e11f63919df16691532389552643fcc13b873c078",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p10",
          "text": "4. 사안에의 적용 및 결론 - 3점",
          "kind": "heading",
          "sha256": "4432412e4dc88f627880029c022fa4fe460352cd946cbeb92e14fef61513ee7e",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p11",
          "text": "- 갑 주장의 대여금채권의 부존재에 기판력 발생하지 않으므로 후소에서 이와 다른 주장 가능, 따라서 갑의 후소에서의 청구가 전소 확정판결의 기판력에 저촉된다는 을의 항변은 타당하지 않음",
          "kind": "argument",
          "sha256": "f57d1fe7d251bf426c2989b9689abea6b1382c6dcf36cf0386367e0601d3d889",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        },
        {
          "id": "class-4주-문1:s0:p12",
          "text": "(그러나 전소확정판결이유에서 판단된 위 대여금채권 -부존재 사실이 후소에서 이를 채용할 수 없는 특별한 사정이 없는 한 유력한 증거자료가 되므로, 후소법원은 특별한 사정이 없는 한 청구 기각판결을 해야 할 것임)",
          "kind": "argument",
          "sha256": "59a7fe2027c04047605533fdbab4be24469b7262af0a9c491d5283782db6be6d",
          "sourceId": "s7d6eb58f2f",
          "sourceFile": "민사소송법사례연습 4주차 답안.txt",
          "pages": [
            1
          ]
        }
      ],
